module tb;
    // Inputs as regs
    reg        clk;
    reg        reset;

    // Outputs as wires
    wire [4:0] q;

    // Instantiate TopModule
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Expected sequence tracking for a 5-bit maximal-length Galois LFSR
    // with taps at 5 and 3 (polynomial: x^5 + x^3 + 1).
    // Initial state = 5'b00001 (1).
    // Period for 5-bit is 2^5 - 1 = 31 states before repeating.
    reg [4:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        expected_q = 5'b00001;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        if (q !== 5'b00001) begin
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        reset = 0; // Release reset

        // Check the first 40 clock cycles to ensure correct sequencing and periodicity
        for (i = 0; i < 40; i = i + 1) begin
            // Sample before clock edge or check immediately after posedge
            @(posedge clk);
            #1; // small delay for propagation

            // Compute expected next state via software model of the same Galois LFSR
            // q_next = {q[0], q[4], q[3] ^ q[0], q[2], q[1]}
            expected_q = {expected_q[0], expected_q[4], expected_q[3] ^ expected_q[0], expected_q[2], expected_q[1]};

            if (q !== expected_q) begin
                $display("Time %0t: Mismatch! q = %b, expected_q = %b", $time, q, expected_q);
                errors = errors + 1;
            end
        end

        // Test asynchronous/synchronous reset behavior mid-stream
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 5'b00001) begin
            $display("Time %0t: Reset failure! q = %b", $time, q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        #1;
        expected_q = 5'b00001;
        if (q !== expected_q) begin
            $display("Time %0t: Post-reset release failure! q = %b", $time, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
